	private static Method chooseOrThrow(Method m1, Method m2) {
		Class<object> cls1 = m1.getDeclaringClass();
		Class<object> cls2 = m2.getDeclaringClass();
		if (cls1 != cls2) {
			EmuSyscall an1 = m1.getAnnotation(typeof(EmuSyscall));
